// Regenerates product routes, validators and TypeScript types from the shared contracts.
// Inputs live in the private contracts and shared wire schema; outputs are committed so
// product-only checkouts build offline. Never edit files under src/generated by hand.
import { readFile, writeFile, mkdir, rm } from "node:fs/promises";
import { createHash } from "node:crypto";
import Ajv from "ajv/dist/2020.js";
import addFormats from "ajv-formats";
import standaloneCode from "ajv/dist/standalone/index.js";
import { compile } from "json-schema-to-typescript";

const root = new URL("../../", import.meta.url);
const schemaText = await readFile(
  new URL(
    "intelligence/src/auralis_intelligence/contracts/agent-v1.schema.json",
    root,
  ),
  "utf8",
);
const apiText = await readFile(
  new URL("../contracts/agent-product-api.openapi.json", root),
  "utf8",
);
const schema = JSON.parse(schemaText);
const api = JSON.parse(apiText);
const ajv = new Ajv({
  strict: false,
  code: { source: true, esm: true },
  allErrors: true,
});
addFormats(ajv);
ajv.addSchema(schema, "wire");
const routes = {};
const names = new Set();
function definition(value) {
  const ref = value?.content?.["application/json"]?.schema?.$ref;
  if (!ref) return null;
  const name = ref.split("/").at(-1);
  names.add(name);
  return name;
}
for (const [path, methods] of Object.entries(api.paths)) {
  for (const [method, operation] of Object.entries(methods)) {
    routes[`${method.toUpperCase()} ${path}`] = {
      request: definition(operation.requestBody),
      responses: Object.fromEntries(
        Object.entries(operation.responses).map(([status, response]) => [
          status,
          definition(response),
        ]),
      ),
    };
  }
}
const sorted = [...names].sort();
const exports = {};
for (const name of sorted) {
  const id = `wire#/$defs/${name}`;
  ajv.getSchema(id);
  exports[name] = id;
}
const target = new URL("../src/generated/", import.meta.url);
await mkdir(target, { recursive: true });
await rm(new URL("validators.cjs", target), { force: true });
const banner =
  "// Generated by scripts/generate.mjs from the shared contracts. Do not edit.\n";
// Ajv's ESM output still calls require() for its runtime helpers. Rewrite those calls into
// namespace imports and normalise CommonJS interop so Node, Vite and Rolldown agree.
const modules = [];
const code = standaloneCode(ajv, exports).replace(
  /require\("([^"]+)"\)/g,
  (_, specifier) => {
    let index = modules.indexOf(specifier);
    if (index < 0) index = modules.push(specifier) - 1;
    return `__cjs(__m${index})`;
  },
);
const imports = modules
  .map(
    (specifier, index) => `import * as __m${index} from "${specifier}.js";\n`,
  )
  .join("");
const interop =
  'const __cjs = (ns) => { const d = ns.default; return d && typeof d === "object" && ' +
  '("default" in d || "fullFormats" in d) ? d : ns; };\n';
await writeFile(
  new URL("validators.js", target),
  banner + imports + interop + code.replace(/^"use strict";/, ""),
);
await writeFile(
  new URL("validators.d.ts", target),
  banner +
    "type Validator = ((value: unknown) => boolean) & { errors?: unknown };\n" +
    sorted.map((name) => `export declare const ${name}: Validator;\n`).join(""),
);

// TypeScript view of the same definitions. Only the product-facing names are roots.
const typeRoot = {
  title: "ProductContract",
  type: "object",
  additionalProperties: false,
  properties: Object.fromEntries(
    sorted.map((name) => [name, { $ref: `#/$defs/${name}` }]),
  ),
  required: sorted,
  $defs: schema.$defs,
};
const types = await compile(typeRoot, "ProductContract", {
  bannerComment: banner.trim(),
  additionalProperties: false,
  declareExternallyReferenced: true,
  enableConstEnums: false,
  strictIndexSignatures: true,
  unreachableDefinitions: false,
  format: true,
  ignoreMinAndMaxItems: true,
  maxItems: -1,
});
await writeFile(new URL("types.ts", target), types);
await writeFile(
  new URL("routes.json", target),
  JSON.stringify(routes, null, 2) + "\n",
);
await writeFile(
  new URL("provenance.json", target),
  JSON.stringify(
    {
      product_revision: api.info.version,
      schema_sha256: createHash("sha256").update(schemaText).digest("hex"),
      openapi_sha256: createHash("sha256").update(apiText).digest("hex"),
    },
    null,
    2,
  ) + "\n",
);
const fixtures = JSON.parse(
  await readFile(
    new URL("intelligence/tests/fixtures/java-integration-cases.json", root),
    "utf8",
  ),
);
await writeFile(
  new URL("fixtures.json", target),
  JSON.stringify(
    fixtures.filter((row) => names.has(row.definition)),
    null,
    2,
  ) + "\n",
);
console.log("Generated product routes, validators and types from contracts.");
